css_extra:
.sl .tb2 tr.grp td { background:var(--azc) !important; box-shadow:inset 3px 0 0 var(--bem); font-size:14px; color:var(--aze) }
.sl .tb2 td.meta { background:var(--vd-bg); color:var(--vd-tx); font-weight:700 }
#s4 .fluxo { margin:0; gap:6px; flex-wrap:nowrap }
#s4 .fluxo .et { flex:1 1 0; padding:9px 10px; display:flex; flex-direction:column; align-items:center; gap:2px }
#s4 .fluxo .et .num { margin-bottom:2px }
#s4 .fluxo .et b { color:var(--aze); font-size:16px }
#s4 .fluxo .et small { font-size:13px; line-height:1.3; color:var(--tx2, #4a5560) }
#s4 .fluxo .st { font-size:1.4em }
#s5 .tb2, #s6 .tb2 { table-layout:fixed; margin:4px 0 0 }
#s5 .tb2 th, #s6 .tb2 th { padding:6px 12px }
#s5 .tb2 td, #s6 .tb2 td { padding:7px 12px }
#s5 .tb2 th:first-child, #s6 .tb2 th:first-child { width:38% }
#s5 .tb2 th:nth-child(2), #s6 .tb2 th:nth-child(2) { width:36% }
#s5 .card, #s6 .card { padding:10px 14px }
#s5 .card h3, #s6 .card h3 { margin-bottom:4px }
#s8 .tb2 td, #s8 .tb2 th { padding:6px 10px; font-size:14.5px }
#s8 .lins { gap:8px }
#s8 .lin { padding:7px 12px }
#s9 .lins { gap:10px }
#s10 .tb2 td, #s10 .tb2 th { padding:11px 12px; font-size:15.5px }
#s10 .tb2 td:first-child { width:17% } #s10 .tb2 td:nth-child(2) { width:14% } #s10 .tb2 td:nth-child(3) { width:19% }
#s3 .kpi > div { padding:8px 12px } #s3 .kpi span { font-size:13.5px; line-height:1.3 }
#s11 .fig img { max-height:128px }
#s11 .col:last-child .cap { margin:2px 0 6px; font-size:12.5px }
#s11 .col:last-child { justify-content:center }
#s11 .faixa-az + .faixa-az { margin-top:0 }
